    assert "Length of 'foo' must be >= 3: 2" in str(e)
else:
    raise AssertionError("Should have raised ValueError for string")

try:
    MyClass(foo=[1, 2])
except ValueError as e:
    print(f"Caught expected error for list: {e}")
    assert "Length of 'foo' must be >= 3: 2" in str(e)
